    {
      "title": "Alexander's Vengeful Arrival",
      "start_block": "B044",
      "end_block": "B055",
      "hook": "The thug's smug smile drops as heavy footsteps pound in the darkness, signaling an imminent arrival.",
      "cliffhanger": "Alexander stands between Juliana and the thugs, staring them down with deadly intent as tension swells.",
      "why": "Creates high anticipation for the confrontation by cutting right as the protector arrives but before the fight begins.",
      "context_gap": "None; the viewer sees a hero arrive to save the victim from bullies."
    },
    {
      "title": "Blood on Bandaged Hands",
      "start_block": "B036",
      "end_block": "B042",
      "hook": "Fresh crimson blood seeps profusely through white gauze bandages as the heroine crawls toward crushed flowers.",
      "cliffhanger": "A thug hoists his club above his head to crush the remaining herbs right before the crying woman.",
      "why": "Visually shocking imagery of injury combined with a looming physical attack creates immediate urgency.",
      "context_gap": "None; the viewer sees a wounded woman being threatened with violence."
    }
  ],
